import{_ as t,o,c as s,a0 as n}from"./chunks/framework.BFac62L4.js";const u=JSON.parse('{"title":"Account Console","description":"","frontmatter":{},"headers":[],"relativePath":"guide/deployment/account-console.md","filePath":"guide/deployment/account-console.md"}'),a={name:"guide/deployment/account-console.md"};function i(c,e,d,r,l,h){return o(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="account-console" tabindex="-1">Account Console <a class="header-anchor" href="#account-console" aria-label="Permalink to &quot;Account Console&quot;">​</a></h1><p>The account console is the end-user self-service surface. It is a client-side single-page application (the <code>@authup/client-account-console</code> package) served by <code>@authup/server-account-console</code> on the IdP origin at <code>&lt;publicUrl&gt;/console/account</code> by default. <code>authup start</code> runs that service alongside the API on one listener; <code>authup start console account</code> runs it alone, on its own port, for a <a href="./console-replicas.html">split deployment</a>. It works in every deployment, including ones that run with the admin console disabled, and gives each of your applications a stable &quot;Manage account&quot; link target.</p><p>It covers:</p><table tabindex="0"><thead><tr><th>Page</th><th>Path</th><th>What a user can do</th></tr></thead><tbody><tr><td>Account</td><td><code>/console/account</code></td><td>Edit profile basics (name, display name, email)</td></tr><tr><td>Password</td><td><code>/console/account/password</code></td><td>Change the password</td></tr><tr><td>Authenticators</td><td><code>/console/account/authenticators</code></td><td>Enroll and remove second factors (TOTP, recovery codes, email, passkeys)</td></tr><tr><td>Connected accounts</td><td><code>/console/account/connected-accounts</code></td><td>Link and unlink external identity-provider accounts (e.g. Facebook, Google, any OAuth2/OIDC provider of the realm)</td></tr><tr><td>Sessions</td><td><code>/console/account/sessions</code></td><td>See active sessions, revoke one, or log out all other devices</td></tr><tr><td>Applications</td><td><code>/console/account/applications</code></td><td>Review and revoke granted application consents, and open an application that registered a home URL (<code>baseUrl</code>)</td></tr></tbody></table><h2 id="sign-in" tabindex="-1">Sign-in <a class="header-anchor" href="#sign-in" aria-label="Permalink to &quot;Sign-in&quot;">​</a></h2><p>Served on the IdP origin, the console signs in <strong>through the server</strong> and never holds an OAuth2 token in JavaScript. A user visiting <code>/console/account</code> without a session picks a realm (a single-realm deployment skips the picker), and the page navigates to <code>GET /console/account/login/start</code>. The server mints the PKCE verifier and the <code>state</code>, parks them behind a short-lived cookie and redirects to the hosted login; <code>GET /console/account/callback</code> then redeems the code, revokes the tokens it received and hands the browser an opaque, <code>HttpOnly</code> session cookie naming the session row. Those two routes are the only <code>/console/account</code> paths the API answers; everything else under it is the console service. The admin console signs in the same way, and both surfaces share the single session on that origin.</p><p>The flow is an authorization-code flow with PKCE either way, against the per-realm <code>account-console</code> system client (see <a href="./provisioning.html#per-realm-system-clients">Provisioning</a>). What the server-side variant changes is who holds the credential. A bundle hosted standalone on a foreign origin cannot present a <code>SameSite=Strict</code> cookie, so it runs the same flow in the browser and keeps its tokens there; that is decided at runtime, not configured.</p><p>An existing session on the IdP origin is reused, so no second session row is created. Attribution is per token (<code>auth_session_tokens.client_id</code>), so the tokens the account console obtains name the <code>account-console</code> client. The session row itself records no application: its <code>client_id</code> is a subject foreign key and stays null for a user&#39;s session.</p><p>A deep link may pin the realm up front: <code>&lt;publicUrl&gt;/console/account?realmId=&lt;id-or-name&gt;</code>.</p><h2 id="connected-accounts" tabindex="-1">Connected accounts <a class="header-anchor" href="#connected-accounts" aria-label="Permalink to &quot;Connected accounts&quot;">​</a></h2><p>The connected-accounts page lists the realm&#39;s enabled OAuth2/OIDC identity providers. Connecting one sends the user through the external provider and binds the returned external identity to the CURRENT user, so future logins through that provider land on this account instead of creating a new user. An external identity that is already linked to another user is rejected.</p><p>Disconnecting removes the link. The last linked account of a user without a password cannot be disconnected: it may be the only way into the account. Set a password first.</p><p>Administrators see a user&#39;s linked accounts on the user detail page of the <a href="./configuration-client-admin-console.html">admin console</a> (permissions <code>identity_provider_account_read</code> / <code>identity_provider_account_delete</code>); the API surface is <code>GET /identity-provider-accounts</code> and <code>DELETE /identity-provider-accounts/:id</code>, self-scoped for callers without the read permission.</p><h2 id="restricting-access" tabindex="-1">Restricting access <a class="header-anchor" href="#restricting-access" aria-label="Permalink to &quot;Restricting access&quot;">​</a></h2><p>Binding an access policy to a realm&#39;s <code>account-console</code> client (<code>accessPolicyId</code>) denies new sign-ins to the surface for identities that fail the policy; a denied sign-in ends on a readable &quot;access denied&quot; page. The same admission-control caveats as for the admin console apply (see the tip in <a href="./provisioning.html#per-realm-system-clients">Provisioning</a>).</p><h2 id="disabling-the-surface" tabindex="-1">Disabling the surface <a class="header-anchor" href="#disabling-the-surface" aria-label="Permalink to &quot;Disabling the surface&quot;">​</a></h2><p>Operators with their own self-service portal can turn the surface off:</p><div class="language-dotenv vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">dotenv</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">ACCOUNT_CONSOLE_ENABLED</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">false</span></span></code></pre></div><p>(<code>accountConsole.enabled</code> / <code>ACCOUNT_CONSOLE_ENABLED</code>, default <code>true</code>.) The routes then serve a localized &quot;not enabled&quot; notice instead of the surface, so stale links do not dead-end. The flag is also reported in the <code>features</code> block of the public status endpoint (<code>GET /</code>).</p><h2 id="standalone-hosting" tabindex="-1">Standalone hosting <a class="header-anchor" href="#standalone-hosting" aria-label="Permalink to &quot;Standalone hosting&quot;">​</a></h2><p>The console is an ordinary OAuth2 relying party, so the same built bundle can be hosted on any static host or another origin instead of (or in addition to) the embedded serving:</p><ol><li><p>Take the <code>dist/</code> directory of the <code>@authup/client-account-console</code> package and serve it under a path of your host, <code>/console/account</code> by default.</p></li><li><p>Inject the runtime configuration by replacing the <code>&lt;!--account-config--&gt;</code> marker in <code>index.html</code> (or by any script that runs before the app bundle):</p><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">script</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">window.__AUTHUP__ </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;apiUrl&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://auth.example.com&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;basePath&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/console/account&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">};</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">script</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p><code>apiUrl</code> is the authup server&#39;s public URL. Without injected configuration the app assumes it is served by (or proxied to) the authup origin itself and derives the API URL from its own location.</p></li><li><p>Register the host&#39;s origin in the authup server&#39;s <code>TRUSTED_ORIGINS</code>. The per-realm <code>account-console</code> client&#39;s redirect and post-logout allowlists derive from that origin set, so sign-in and sign-out round-trips are permitted on the next start.</p></li></ol><p>Session continuity is preserved on a foreign origin: the login happens on the hosted authorize page either way, and the code exchange reuses the session created there.</p>`,23)])])}const g=t(a,[["render",i]]);export{u as __pageData,g as default};
